// The Svelte element typings generator (IC-04, FR-004): exact output for a fixture manifest, the staleness check over
// every generated file, the loud failure on a type that @moes-media/mission-ui does not export, and the real run over the
// committed manifest. Temporary trees live under the OS temp directory and are removed through their own handle.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { checkGenerated, ELEMENTS_FILE, exportedNames, generate, INDEX, MANIFEST, writeGenerated } from './typings.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SCRIPT = join(ROOT, 'scripts', 'typings.mjs');

const fixtureManifest = (fields, events) => ({
  schemaVersion: '1.0.0',
  modules: [
    {
      kind: 'javascript-module',
      path: 'src/elements/sk-fixture/sk-fixture.ts',
      declarations: [
        {
          kind: 'class',
          name: 'SkFixture',
          tagName: 'sk-fixture',
          customElement: true,
          members: fields,
          events,
        },
      ],
    },
  ],
});

const ONE_PROPERTY = [
  { kind: 'field', name: 'items', type: { text: 'FixtureItem[] | null' }, default: 'null' },
  // A private field and a method are not part of the element's public surface.
  { kind: 'field', name: 'cache', privacy: 'private', type: { text: 'Map<string, number>' } },
  { kind: 'method', name: 'render' },
];
const ONE_EVENT = [{ name: 'sk-pick', type: { text: 'CustomEvent<FixturePickDetail>' } }];
const FIXTURE_INDEX = "export type { FixtureItem, FixturePickDetail } from './fixture.js';\n";

const EXPECTED_FIXTURE = [
  '// GENERATED by scripts/typings.mjs from packages/mission-ui/custom-elements.json — do not edit.',
  '// The Svelte typings of the mission-ui elements: each public property, and one `on<event>` handler per declared event,',
  '// so a renamed property or event fails svelte-check (FR-004). Regenerate with `node scripts/typings.mjs`.',
  '// The reference brings in the `*.css?inline` declaration of mission-ui, whose sources the imports below pull in.',
  '/// <reference path="../../../mission-ui/src/css-inline.d.ts" />',
  'import type {',
  '  FixtureItem,',
  '  FixturePickDetail,',
  "} from '@moes-media/mission-ui';",
  '',
  "declare module 'svelte/elements' {",
  '  export interface SvelteHTMLElements {',
  "    'sk-fixture': Omit<HTMLAttributes<HTMLElement>, 'items'> & {",
  '      items?: FixtureItem[] | null;',
  "      'onsk-pick'?: (event: CustomEvent<FixturePickDetail>) => void;",
  '    };',
  '  }',
  '}',
  '',
  'export {};',
  '',
].join('\n');

/** A temporary tree holding a manifest and an index; returns its root. */
function tree(manifest, indexText) {
  const root = mkdtempSync(join(tmpdir(), 'sk-typings-'));
  mkdirSync(join(root, dirname(MANIFEST)), { recursive: true });
  mkdirSync(join(root, dirname(INDEX)), { recursive: true });
  writeFileSync(join(root, MANIFEST), JSON.stringify(manifest, null, 2));
  writeFileSync(join(root, INDEX), indexText);
  return root;
}

test('a fixture manifest with one element, one property and one event produces the expected text', () => {
  const files = generate(fixtureManifest(ONE_PROPERTY, ONE_EVENT), FIXTURE_INDEX);
  assert.deepEqual([...files.keys()], [ELEMENTS_FILE]);
  assert.equal(files.get(ELEMENTS_FILE), EXPECTED_FIXTURE);
});

test('members and elements are emitted in sorted order, whatever the manifest order', () => {
  const fields = [
    { kind: 'field', name: 'zeta', type: { text: 'string' } },
    { kind: 'field', name: 'alpha', type: { text: 'boolean' } },
  ];
  const events = [
    { name: 'sk-zed', type: { text: 'CustomEvent<null>' } },
    { name: 'sk-abc', type: { text: 'CustomEvent<null>' } },
  ];
  const manifest = fixtureManifest(fields, events);
  manifest.modules.unshift({
    kind: 'javascript-module',
    path: 'src/elements/sk-zz/sk-zz.ts',
    declarations: [{ kind: 'class', name: 'SkZz', tagName: 'sk-zz', customElement: true, members: [], events: [] }],
  });
  const text = generate(manifest, '').get(ELEMENTS_FILE);
  const order = ['alpha?: boolean;', 'zeta?: string;', "'onsk-abc'?", "'onsk-zed'?", "'sk-fixture':", "'sk-zz':"];
  const at = order.map((s) => text.indexOf(s));
  assert.equal(at.filter((i) => i >= 0).length, order.length, `every member is present: ${JSON.stringify(at)}`);
  const memberAt = at.slice(0, 4);
  assert.deepEqual(memberAt, [...memberAt].sort((a, b) => a - b));
  assert.ok(at[4] < at[5], 'sk-fixture before sk-zz');
  // Built-in types only: no import line at all.
  assert.equal(text.includes('import type'), false);
  assert.equal(generate(manifest, '').get(ELEMENTS_FILE), text, 'deterministic');
});

test('an unknown event detail type fails with its name; the exported one (positive control) passes', () => {
  assert.throws(
    () => generate(fixtureManifest(ONE_PROPERTY, ONE_EVENT), "export type { FixtureItem } from './fixture.js';\n"),
    /sk-fixture\.sk-pick names 'FixturePickDetail', which @moes-media\/mission-ui does not export/,
  );
  assert.doesNotThrow(() => generate(fixtureManifest(ONE_PROPERTY, ONE_EVENT), FIXTURE_INDEX));
});

test('an unknown property type fails with its name, and `any` is never emitted', () => {
  assert.throws(
    () => generate(fixtureManifest(ONE_PROPERTY, ONE_EVENT), "export type { FixturePickDetail } from './fixture.js';\n"),
    /sk-fixture\.items names 'FixtureItem', which @moes-media\/mission-ui does not export/,
  );
  const anyField = [{ kind: 'field', name: 'loose', type: { text: 'any[]' } }];
  assert.throws(() => generate(fixtureManifest(anyField, []), ''), /sk-fixture\.loose names 'any'/);
});

test('string literals in a type are emitted as written and are not taken for type names', () => {
  const field = [{ kind: 'field', name: 'mode', type: { text: "'Compact' | \"Wide\" | Readonly<Record<string, number>>" } }];
  const text = generate(fixtureManifest(field, []), '').get(ELEMENTS_FILE);
  assert.ok(text.includes("mode?: 'Compact' | \"Wide\" | Readonly<Record<string, number>>;"));
});

test('exportedNames reads type and value exports of the index', () => {
  const names = exportedNames(
    "export { A, B as C } from './a.js';\nexport type { D } from './d.js';\nexport const E = 1;\nexport interface F {}\n",
  );
  assert.deepEqual([...names].sort(), ['A', 'C', 'D', 'E', 'F']);
});

test('--check passes on freshly generated files and reports each altered or missing file as stale', () => {
  const root = tree(fixtureManifest(ONE_PROPERTY, ONE_EVENT), FIXTURE_INDEX);
  try {
    writeGenerated(root);
    assert.deepEqual(checkGenerated(root), []);
    const cli = (args) => spawnSync(process.execPath, [SCRIPT, ...args, '--root', root], { encoding: 'utf8' });
    const clean = cli(['--check']);
    assert.equal(clean.status, 0, clean.stderr);

    const target = join(root, ELEMENTS_FILE);
    writeFileSync(target, readFileSync(target, 'utf8').replace('items?:', 'itemz?:'));
    assert.deepEqual(checkGenerated(root), [`${ELEMENTS_FILE} is stale`]);
    const stale = cli(['--check']);
    assert.equal(stale.status, 1);
    assert.match(stale.stderr, /elements\.d\.ts is stale/);

    rmSync(target);
    assert.deepEqual(checkGenerated(root), [`${ELEMENTS_FILE} is stale`]);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('--check reports a file in the generated directory that the generator does not write', () => {
  const root = tree(fixtureManifest(ONE_PROPERTY, ONE_EVENT), FIXTURE_INDEX);
  try {
    writeGenerated(root);
    const stray = join(dirname(join(root, ELEMENTS_FILE)), 'intents.ts');
    writeFileSync(stray, 'export {};\n');
    assert.deepEqual(checkGenerated(root), [`${dirname(ELEMENTS_FILE)}/intents.ts is not generated by scripts/typings.mjs`]);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('the real run types exactly the 15 elements of custom-elements.json and matches the committed file', () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, MANIFEST), 'utf8'));
  // Oracle: the manifest itself, read independently of the generator.
  const tags = manifest.modules.flatMap((m) => (m.declarations ?? []).filter((d) => d.tagName).map((d) => d.tagName));
  assert.equal(tags.length, 15);
  const text = generate(manifest, readFileSync(join(ROOT, INDEX), 'utf8')).get(ELEMENTS_FILE);
  const typed = [...text.matchAll(/^ {4}'(sk-[a-z-]+)': /gm)].map((m) => m[1]);
  assert.equal(typed.length, 15);
  assert.deepEqual(typed, [...tags].sort());
  let events = 0;
  for (const tag of tags) {
    const decl = manifest.modules.flatMap((m) => m.declarations ?? []).find((d) => d.tagName === tag);
    for (const ev of decl.events ?? []) {
      events += 1;
      assert.ok(text.includes(`'on${ev.name}'?: (event: ${ev.type.text}) => void;`), `${tag} ${ev.name}`);
    }
  }
  assert.equal(events, manifest.modules.flatMap((m) => m.declarations ?? []).reduce((n, d) => n + (d.events ?? []).length, 0));
  assert.ok(events > 0);
  assert.equal(/\bany\b/.test(text), false, 'no any');
  assert.equal(readFileSync(join(ROOT, ELEMENTS_FILE), 'utf8'), text);
  assert.deepEqual(checkGenerated(ROOT), []);
});
